<div class="page-heading"><div><p class="eyebrow">Schedule #<?= $schedule->getKey() ?></p><h1><?= e($schedule->getDate()) ?> · <?= e($schedule->getTimeSlot()) ?></h1><p class="lead"><?= e($schedule->getStrategy()) ?> Strategy · <?= e($schedule->getStatus()) ?></p></div><div class="button-row"><?php if (UserPermissions::can($user, 'schedule.manage') && $schedule->getStatus() === 'Planned'): ?><a class="button" href="<?= url('schedule/edit/' . $schedule->getKey()) ?>">Edit</a><?php endif; ?><a class="button button-secondary" href="<?= UserPermissions::can($user, 'schedule.manage') ? url('schedule') : url('schedule/my') ?>">Back</a></div></div>
<?php if ($schedule->getNotes()): ?><section class="content-card"><strong>Notes</strong><p><?= e($schedule->getNotes()) ?></p></section><?php endif; ?>
<div class="table-scroll"><table class="table"><thead><tr><th>Bin</th><th>Cleaner</th><th>Priority/reason</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($assignments as $assignment): ?><tr><td><?= e($assignment->getBin()?->getBinCode() ?? 'Unknown') ?><br><small><?= e($assignment->getBin()?->getLocation()?->getFullLabel() ?? '') ?></small></td><td><?= e($assignment->getCleaner()?->getFullName() ?? 'Unknown') ?></td><td><strong><?= e($assignment->getPriority()) ?></strong><br><?= e($assignment->getReason() ?? '') ?></td><td><?= e($assignment->getStatus()) ?></td><td><?php if ($assignment->getStatus() === 'Assigned' && $assignment->getCleanerId() === $user->getKey()): ?><a href="<?= url('schedule/complete/' . $assignment->getKey()) ?>">Complete</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php if (UserPermissions::can($user, 'schedule.manage') && $schedule->getStatus() === 'Planned'): ?><form method="post" action="<?= url('schedule/cancel/' . $schedule->getKey()) ?>" class="danger-zone" onsubmit="return confirm('Cancel this schedule and skip its open assignments?');"><?= csrfField() ?><div><strong>Cancel schedule</strong><p>Completed records remain; open assignments are marked Skipped.</p></div><button class="button button-danger" type="submit">Cancel schedule</button></form><?php endif; ?>
